files.schemas/tree.schema.json:
{
 "$schema": "urn:semantic-agent-schema:published-language:abstract:v1",
 "$id": "urn:example:sample:tree:v1",
 "title": "木",
 "description": "節が子の節を持つ木である。",
 "type": "object",
 "required": [
  "$schema",
  "root"
 ],
 "properties": {
  "$schema": {
   "const": "urn:example:sample:tree:v1"
  },
  "root": {
   "title": "根の節",
   "description": "木の根である。",
   "$ref": "#/$defs/node"
  }
 },
 "$defs": {
  "node": {
   "type": "object",
   "title": "節",
   "description": "名前と子の節を持つ。",
   "properties": {
    "name": {
     "type": "string",
     "title": "名前",
     "description": "節の名前である。",
     "x-prompt": {
      "rules": [
       {
        "id": "name-is-noun",
        "rule": "名前は名詞で書く。",
        "why": "動詞だと何の節かが分からない。",
        "check": "名詞句かを見る。",
        "bad": [
         {
          "value": "読む",
          "note": "動詞で、何の節かが分からない。"
         }
        ],
        "good": [
         {
          "value": "目次"
         }
        ]
       }
      ]
     }
    },
    "children": {
     "type": "array",
     "title": "子",
     "description": "子の節の並びである。",
     "items": {
      "$ref": "#/$defs/node"
     }
    }
   }
  }
 }
}
